functions._asiFmtBytes:
function _asiFmtBytes(n) {
  if (n == null || isNaN(n)) return "—";
  if (n < 1024) return n + " B";
  if (n < 1048576) return (n / 1024).toFixed(1) + " KB";
  if (n < 1073741824) return (n / 1048576).toFixed(2) + " MB";
  return (n / 1073741824).toFixed(2) + " GB";
}

// localStorage rows — every key, ordered by size (largest first).

functions._asiReadLocalStorage:
function _asiReadLocalStorage() {
  var rows = [];
  var total = 0;
  try {
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k == null) continue;
      var v = "";
      try { v = localStorage.getItem(k) || ""; } catch (e) { v = ""; }
      // Browser localStorage is UTF-16 so each char ≈ 2 bytes. Approximate.
      var sz = (String(v).length + String(k).length) * 2;
      total += sz;
      rows.push({ key: k, size: sz, value: v, preview: String(v).slice(0, 80) });
    }
  } catch (e) { /* iframe storage may throw */ }
  rows.sort(function (a, b) { return b.size - a.size; });
  return { rows: rows, total: total };
}

// IDB stores — for each known store, count rows + sum approx byte size
// of JSON-serialized rows. Uses eli.storage.getAll which is already cheap.

functions._asiReadIdb:
function _asiReadIdb() {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.getAll !== "function") {
    return Promise.resolve([]);
  }
  // Pull the list of stores from window globals (kernel exposes
  // STORE_* constants on window for v2 compat). Falls back to a fixed
  // list if those aren't present.
  var storeNames = [
    "templates", "playbooks", "risk_rules", "requesters", "bd_templates",
    "stats", "config", "trophies", "catalog", "prompts", "email_templates",
    "agreement_types", "loading_msgs", "cleaner_rules", "exec_brief_terms",
    "json_tools", "wrongness_captures",
  ];
  var seen = {};
  return Promise.all(storeNames.map(function (s) {
    if (seen[s]) return Promise.resolve(null);
    seen[s] = true;
    return window.eli.storage.getAll(s).then(function (rows) {
      var count = (rows || []).length;
      var size = 0;
      try { size = JSON.stringify(rows || []).length; } catch (e) { size = 0; }
      return { name: s, count: count, size: size, error: null };
    }).catch(function (err) {
      return { name: s, count: 0, size: 0, error: (err && err.message) || "n/a" };
    });
  })).then(function (results) {
    return results.filter(Boolean).filter(function (r) {
      // Hide stores that errored OR are empty — keeps the view focused
      // on what's actually using space.
      return r.error || r.count > 0;
    }).sort(function (a, b) { return b.size - a.size; });
  });
}

functions._asiSizeClass:
function _asiSizeClass(size) {
  if (size > 102400) return "_asi_row_size _asi_row_size_xl"; // > 100 KB
  if (size > 10240)  return "_asi_row_size _asi_row_size_lg"; // > 10 KB
  return "_asi_row_size";
}

functions._asiRenderQuota:
function _asiRenderQuota() {
  var box = document.getElementById("asiQuotaBody");
  if (!box) return;
  if (!navigator.storage || !navigator.storage.estimate) {
    box.innerHTML = '<div style="font-size:11px; color:#94a3b8;">Quota API not supported in this environment.</div>';
    return;
  }
  navigator.storage.estimate().then(function (est) {
    var used = est.usage || 0;
    var quota = est.quota || 0;
    var pct = quota ? (used / quota) * 100 : 0;
    var color = pct > 80 ? "#dc2626" : pct > 50 ? "#f59e0b" : "#16a34a";
    box.innerHTML =
      '<div class="_asi_quota_top">' +
        '<span>Used: <strong>' + _asiFmtBytes(used) + '</strong></span>' +
        '<span>Quota: <strong>' + _asiFmtBytes(quota) + '</strong></span>' +
      '</div>' +
      '<div class="_asi_quota_bar"><div class="_asi_quota_fill" style="width:' + pct.toFixed(1) + '%; background:' + color + ';"></div></div>' +
      '<div class="_asi_quota_pct" style="color:' + color + ';">' + pct.toFixed(1) + '% used</div>';
  }).catch(function () {
    box.innerHTML = '<div style="font-size:11px; color:#94a3b8;">Quota API failed.</div>';
  });
}

functions._asiRenderLocalStorage:
function _asiRenderLocalStorage(filterStr) {
  var box = document.getElementById("asiLsBody");
  var meta = document.getElementById("asiLsMeta");
  if (!box) return;
  var ls = _asiReadLocalStorage();
  var f = String(filterStr || "").trim().toLowerCase();
  var visible = f
    ? ls.rows.filter(function (r) { return (r.key.toLowerCase().indexOf(f) !== -1) || (r.preview.toLowerCase().indexOf(f) !== -1); })
    : ls.rows;
  if (meta) {
    meta.innerHTML = '<strong>' + ls.rows.length + '</strong> key' + (ls.rows.length === 1 ? '' : 's') +
      ' · total <strong>' + _asiFmtBytes(ls.total) + '</strong>' +
      (f && visible.length !== ls.rows.length ? ' · ' + visible.length + ' matching' : '');
  }
  if (!visible.length) {
    box.innerHTML = '<div class="_asi_empty">' + (f ? 'No keys match "' + _asiEsc(f) + '".' : 'localStorage is empty.') + '</div>';
    return;
  }
  box.innerHTML = '<div class="_asi_list">' + visible.map(function (r) {
    return '<div class="_asi_row">' +
      '<div class="_asi_row_main">' +
        '<div class="_asi_row_key">' + _asiEsc(r.key) + '</div>' +
        '<div class="_asi_row_preview">' + _asiEsc(r.preview) + (r.value.length > 80 ? '…' : '') + '</div>' +
      '</div>' +
      '<div class="' + _asiSizeClass(r.size) + '">' + _asiFmtBytes(r.size) + '</div>' +
      '<div class="_asi_row_actions">' +
        '<button class="_asi_btn" data-asi-copy="' + _asiEsc(r.key) + '" title="Copy value to clipboard">📋</button>' +
        '<button class="_asi_btn _asi_btn_danger" data-asi-del="' + _asiEsc(r.key) + '" title="Delete key">🗑</button>' +
      '</div>' +
    '</div>';
  }).join("") + '</div>';
  box.querySelectorAll("[data-asi-copy]").forEach(function (b) {
    b.onclick = function () {
      var k = b.getAttribute("data-asi-copy");
      var v = "";
      try { v = localStorage.getItem(k) || ""; } catch (e) {}
      try { navigator.clipboard.writeText(v); } catch (e) {}
      var orig = b.textContent;
      b.textContent = "✓";
      setTimeout(function () { b.textContent = orig; }, 1000);
      if (typeof showToast === "function") showToast("Copied " + k, "ok");
    };
  });
  box.querySelectorAll("[data-asi-del]").forEach(function (b) {
    b.onclick = function () {
      var k = b.getAttribute("data-asi-del");
      if (!window.eli.ui || typeof window.eli.ui.confirm !== "function") return;
      window.eli.ui.confirm({
        variant: "danger", icon: "🗑",
        title: "Delete localStorage key?",
        message: "Permanently remove <code>" + _asiEsc(k) + "</code> from this install's localStorage. Cannot be undone.",
        confirmLabel: "Delete", cancelLabel: "Cancel",
      }).then(function (ok) {
        if (!ok) return;
        try { localStorage.removeItem(k); } catch (e) {}
        if (typeof showToast === "function") showToast("Deleted " + k, "info");
        var searchEl = document.getElementById("asiLsSearch");
        _asiRenderLocalStorage(searchEl ? searchEl.value : "");
        _asiRenderQuota();
      });
    };
  });
}

functions._asiRenderIdb:
function _asiRenderIdb() {
  var box = document.getElementById("asiIdbBody");
  var meta = document.getElementById("asiIdbMeta");
  if (!box) return;
  box.innerHTML = '<div class="_asi_loading"><span class="_asi_loading_spinner"></span>Reading IDB stores…</div>';
  _asiReadIdb().then(function (stores) {
    var totalRows = stores.reduce(function (a, s) { return a + (s.count || 0); }, 0);
    var totalSize = stores.reduce(function (a, s) { return a + (s.size || 0); }, 0);
    if (meta) {
      meta.innerHTML = '<strong>' + stores.length + '</strong> store' + (stores.length === 1 ? '' : 's') +
        ' · <strong>' + totalRows + '</strong> row' + (totalRows === 1 ? '' : 's') +
        ' · approx <strong>' + _asiFmtBytes(totalSize) + '</strong>';
    }
    if (!stores.length) {
      box.innerHTML = '<div class="_asi_empty">No populated IDB stores found.</div>';
      return;
    }
    box.innerHTML = stores.map(function (s) {
      var err = s.error
        ? '<div style="font-size:10px; color:#b91c1c; margin-top:4px;">error: ' + _asiEsc(s.error) + '</div>'
        : '';
      return '<div class="_asi_idb_store">' +
        '<div class="_asi_idb_store_head">' +
          '<span class="_asi_idb_store_name">' + _asiEsc(s.name) + '</span>' +
          '<span class="_asi_idb_store_count">' + s.count + ' row' + (s.count === 1 ? '' : 's') + '</span>' +
        '</div>' +
        '<div class="_asi_idb_store_size">' + _asiFmtBytes(s.size) + ' approx (JSON-serialized)</div>' +
        err +
      '</div>';
    }).join("");
  });
}

functions.showAdminStorageInspector:
function showAdminStorageInspector() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_asi_root">' +
      '<div class="_asi_header">' +
        '<div>' +
          '<div class="_asi_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_asi_header_title">🔍 Storage Inspector</div>' +
          '<div class="_asi_header_sub">Browser quota, every localStorage key (with size + delete), and every IDB store with row counts.</div>' +
        '</div>' +
        '<button class="_asi_refresh" id="asiRefresh">🔄 Refresh</button>' +
      '</div>' +

      // Quota
      '<div class="_asi_card">' +
        '<div class="_asi_card_head">' +
          '<span class="_asi_card_title">📊 Browser storage quota</span>' +
        '</div>' +
        '<div class="_asi_card_body" id="asiQuotaBody">' +
          '<div class="_asi_loading"><span class="_asi_loading_spinner"></span>Loading…</div>' +
        '</div>' +
      '</div>' +

      // localStorage
      '<div class="_asi_card">' +
        '<div class="_asi_card_head">' +
          '<span class="_asi_card_title">📁 localStorage</span>' +
          '<span class="_asi_card_meta" id="asiLsMeta">—</span>' +
        '</div>' +
        '<div class="_asi_card_body">' +
          '<div class="_asi_search_wrap">' +
            '<input type="text" id="asiLsSearch" placeholder="Filter by key or value preview…">' +
          '</div>' +
          '<div id="asiLsBody"></div>' +
        '</div>' +
      '</div>' +

      // IDB
      '<div class="_asi_card">' +
        '<div class="_asi_card_head">' +
          '<span class="_asi_card_title">🗄 IndexedDB stores</span>' +
          '<span class="_asi_card_meta" id="asiIdbMeta">—</span>' +
        '</div>' +
        '<div class="_asi_card_body" id="asiIdbBody"></div>' +
      '</div>' +

      '<div class="_asi_footer">' +
        'Sizes are approximate — localStorage assumes UTF-16 (2 bytes/char); IDB sizes are JSON-serialized lengths, not the on-disk encoded size. ' +
        'Press <span class="_asi_footer_kbd">R</span> to refresh.' +
      '</div>' +
    '</div>';

  _asiRender("");

  document.getElementById("asiRefresh").onclick = function () {
    var s = document.getElementById("asiLsSearch");
    _asiRender(s ? s.value : "");
  };

  var searchTimer = null;
  document.getElementById("asiLsSearch").oninput = function () {
    if (searchTimer) clearTimeout(searchTimer);
    var val = this.value;
    searchTimer = setTimeout(function () { _asiRenderLocalStorage(val); }, 200);
  };

  // Keyboard: R refreshes (only when not typing).
  var keyHandler = function (e) {
    var tag = (e.target && e.target.tagName) || "";
    if (tag === "INPUT" || tag === "TEXTAREA") return;
    if ((e.key === "r" || e.key === "R") && !e.ctrlKey && !e.metaKey) {
      e.preventDefault();
      var s = document.getElementById("asiLsSearch");
      _asiRender(s ? s.value : "");
    }
  };
  document.addEventListener("keydown", keyHandler);
  window._asiKeyHandler = keyHandler;
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedStorageInspector"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminStorageInspector !== "function") {
      eli.log.event("tool", "admin_storage_inspector_fn_missing", {});
      if (typeof showToast === "function") showToast("Storage Inspector failed to load", "err");
      return;
    }
    try { window.showAdminStorageInspector(); }
    catch (e) {
      eli.log.event("tool", "admin_storage_inspector_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_admin_storage_inspector: _show },
    admin_storage_inspector: { open: _show },
  });

  eli.log.event("tool", "admin_storage_inspector_initialized", {});
}

jsonTools.css:
/* admin_storage_inspector — premium admin UI for inspecting both
   localStorage and IndexedDB. Class prefix `_asi_`. */

._asi_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0 0 24px 0;
}

._asi_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 18px 22px;
  border-bottom: 3px solid #c9a227;
  display: flex; justify-content: space-between; align-items: center;
}
._asi_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif; letter-spacing: 1.4px;
  text-transform: uppercase; color: #c9a227; margin-bottom: 4px;
}
._asi_header_title { font: 800 22px/1.1 "Book Antiqua", Georgia, serif; margin: 0; }
._asi_header_sub { font-size: 11px; color: rgba(255,255,255,0.7); margin-top: 4px; }
._asi_refresh {
  padding: 9px 14px; font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px; text-transform: uppercase;
  background: #c9a227; color: #0d1b2a;
  border: none; cursor: pointer;
  transition: filter 0.15s;
}
._asi_refresh:hover { filter: brightness(0.95); }

._asi_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  margin: 14px 14px 0 14px;
  padding: 0;
}
._asi_card_head {
  display: flex; justify-content: space-between; align-items: center;
  padding: 12px 16px;
  background: linear-gradient(180deg, #fcfcfd, #f8fafc);
  border-bottom: 1px solid #f1f5f9;
}
._asi_card_title {
  font: 800 11px/1 Inter, sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #0f172a;
}
._asi_card_meta {
  font-size: 11px; color: #475569; font-weight: 600;
}
._asi_card_meta strong { color: #1565c0; }
._asi_card_body { padding: 14px 16px; }

/* Quota progress bar */
._asi_quota_top {
  display: flex; justify-content: space-between;
  font-weight: 700; margin-bottom: 6px; font-size: 12px;
}
._asi_quota_bar {
  height: 10px; background: #e2e8f0;
  overflow: hidden; border-radius: 0;
}
._asi_quota_fill {
  height: 100%;
  transition: width 0.4s ease, background 0.4s ease;
}
._asi_quota_pct {
  text-align: right; font-size: 10px;
  margin-top: 4px; font-weight: 800;
}

/* Search bar */
._asi_search_wrap {
  position: relative; margin-bottom: 12px;
}
._asi_search_wrap input {
  width: 100%; padding: 7px 10px 7px 32px;
  font-size: 11px; border: 1px solid #cbd5e1;
  outline: none; box-sizing: border-box;
  transition: border-color 0.15s;
}
._asi_search_wrap input:focus { border-color: #1565c0; }
._asi_search_wrap::before {
  content: "🔍"; position: absolute; left: 10px;
  top: 50%; transform: translateY(-50%);
  font-size: 12px; pointer-events: none;
}

._asi_list { display: flex; flex-direction: column; gap: 4px; }

._asi_row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px; align-items: center;
  padding: 8px 10px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  transition: border-color 0.15s, background 0.15s;
}
._asi_row:hover { border-color: #cbd5e1; background: #fff; }
._asi_row_main { min-width: 0; }
._asi_row_key {
  font: 700 11px/1.2 ui-monospace, Consolas, monospace;
  color: #0f172a;
  overflow-wrap: anywhere;
  word-break: break-word;
}
._asi_row_preview {
  font-size: 10px; color: #64748b;
  overflow: hidden; text-overflow: ellipsis;
  white-space: nowrap; margin-top: 2px;
  font-family: ui-monospace, Consolas, monospace;
}
._asi_row_size {
  font-size: 10px; font-weight: 800;
  text-align: right; white-space: nowrap;
  color: #475569;
}
._asi_row_size_lg { color: #c2410c; }
._asi_row_size_xl { color: #b91c1c; }
._asi_row_actions { display: flex; gap: 4px; }

._asi_btn {
  padding: 5px 9px; font: 700 9px/1 Inter, sans-serif;
  letter-spacing: 0.5px; text-transform: uppercase;
  background: #fff; color: #475569;
  border: 1px solid #cbd5e1; cursor: pointer;
  transition: all 0.15s;
}
._asi_btn:hover { color: #1565c0; border-color: #1565c0; }
._asi_btn_danger { color: #b91c1c; border-color: #fca5a5; }
._asi_btn_danger:hover { color: #b91c1c; background: #fef2f2; border-color: #b91c1c; }

._asi_empty {
  padding: 20px; text-align: center;
  font-size: 11px; color: #94a3b8;
  border: 1px dashed #e2e8f0;
}

._asi_idb_store {
  border: 1px solid #e2e8f0; padding: 10px 12px;
  margin-bottom: 6px; background: #fafbfc;
}
._asi_idb_store_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 4px;
}
._asi_idb_store_name {
  font: 800 11px/1 ui-monospace, Consolas, monospace;
  color: #0f172a;
}
._asi_idb_store_count {
  font-size: 10px; font-weight: 800; color: #1565c0;
  padding: 2px 8px; background: #e3f2fd;
}
._asi_idb_store_size {
  font-size: 10px; color: #64748b;
}

._asi_loading {
  padding: 20px; text-align: center;
  font-size: 11px; color: #64748b;
}
._asi_loading_spinner {
  display: inline-block; width: 14px; height: 14px;
  border: 2px solid #e2e8f0; border-top-color: #1565c0;
  border-radius: 50%;
  animation: _asi_spin 0.8s linear infinite;
  margin-right: 6px; vertical-align: middle;
}
@keyframes _asi_spin { to { transform: rotate(360deg); } }

._asi_footer {
  padding: 10px 16px; margin: 14px;
  font-size: 10px; color: #64748b;
  border-top: 1px solid #e2e8f0;
}
._asi_footer_kbd {
  font-family: ui-monospace, Consolas, monospace;
  padding: 1px 5px; background: #f1f5f9; color: #475569;
  border: 1px solid #cbd5e1; border-bottom-width: 2px;
}
